inputs = ['czvc', 'dzhj', 'wayu', 'ckkfhv', 'gfhkg']
outputs = ['czejcvuc', 'dzhj', 'bbfcvyejcvue', 'ckkfhejcvu', 'gfhkg']

# Manually analyze the differences
print("Detailed Analysis:")
print("==================")

for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")

    # Find differences
    if inp != outp:
        # Find where they differ
        min_len = min(len(inp), len(outp))
        diff_start = None
        diff_end = None

        for j in range(min_len):
            if inp[j] != outp[j]:
                if diff_start is None:
                    diff_start = j
                diff_end = j

        # If no differences found in common length, check lengths
        if diff_start is None:
            if len(inp) != len(outp):
                diff_start = min_len
                diff_end = len(outp) - 1
        else:
            diff_end += 1

        if diff_start is not None:
            print(f"  Differences: from index {diff_start} to {diff_end}")
            if diff_end > diff_start:
                old_sub = inp[diff_start:diff_end]
                new_sub = outp[diff_start:diff_end]
                print(f"  Replace '{old_sub}' with '{new_sub}'")
        else:
            print("  No differences found")
    else:
        print("  No change")
    print()

